/**
 * Stage 8 farming & money advisor: capability check, strategies with atlas presets
 * and Thread (map device) setup, investment and output prices from poe.ninja,
 * the progression path, a money plan and the SSF variant.
 *
 * Facts come from the cited data file (FARMING_DATA, generated by
 * scripts/farming-data.mjs); build numbers from PoB; prices from poe.ninja with their
 * date. Profit per hour is only shown when the player logged sessions (drop rates are
 * not published, so any other per-hour number would be invented).
 */
import { n } from "../format.js";
import { ToolError } from "../pob.js";
import { getProfile } from "../profile.js";
import type { Context } from "../registry.js";
import { exchangePrices, ninjaItemLines } from "../trade/ninja.js";
import { budgetOf } from "../economy/run.js";
import { capabilityText, survival, type CheckResult, type TierVerdict, tierLevels } from "./capability.js";
import { FARMING_DATA as D } from "./data.js";
import { addLog, measuredRate } from "./log.js";

type Strategy = (typeof D.strategies)[number];
const SRC = D.sources as Record<string, { title: string; url: string; edited?: string; outdated?: boolean }>;
const day = (t: number) => new Date(t).toISOString().slice(0, 10);
const oneLine = (stats?: readonly string[]) => (stats ?? []).join(" / ").split("\n").join(" / ");

export interface FarmArgs { farm?: unknown; goal?: unknown; log?: unknown; league: string; leagueNote?: string; points?: number }

const strategyById = (id: string): Strategy | undefined => {
  const k = id.toLowerCase().trim();
  return D.strategies.find((s) => s.id === k || s.name.toLowerCase().startsWith(k) || ("thread" in s && s.thread?.toLowerCase() === k));
};

// --- fit ------------------------------------------------------------------------------------------
function fit(s: Strategy, top: TierVerdict, r: CheckResult, hardcore: boolean): { score: number; why: string[] } {
  const why: string[] = [];
  let score = 0;
  for (const d of s.demands as readonly string[]) {
    if (d === "clear") { const v = top.clear; score += v === "safe" ? 2 : v === "risky" ? 1 : 0; why.push(`clear ${v === "safe" ? "fast" : v === "risky" ? "slow" : "too slow"}`); }
    if (d === "tank") { const v = top.survive; score += v === "safe" ? 2 : v === "risky" ? 1 : 0; why.push(`tankiness ${v}`); }
    if (d === "boss") { const v = survival(r.pinnacle.hits, hardcore); score += v === "safe" ? 2 : v === "risky" ? 1 : 0; why.push(`bossing ${v}`); }
  }
  return { score: score / Math.max(1, s.demands.length), why };
}

// --- prices -----------------------------------------------------------------------------------------
interface Priced { name: string; chaos: number }
async function categoryPrices(league: string, types: string[], notes: Set<string>): Promise<{ prices: Map<string, Map<string, number>>; at?: number }> {
  const all = new Map<string, Map<string, number>>();
  let at: number | undefined;
  for (const type of [...new Set(types)]) {
    try {
      const x = await exchangePrices(league, type);
      all.set(type, x.prices);
      at = at ? Math.min(at, x.at) : x.at;
      if (x.stale) notes.add(`poe.ninja is not answering; ${type} prices are from ${day(x.at)}.`);
    } catch { notes.add(`poe.ninja ${type} prices could not be loaded.`); }
  }
  return { prices: all, at };
}

function outputs(s: Strategy, prices: Map<string, Map<string, number>>): Priced[] {
  const out: Priced[] = [];
  for (const rule of s.ninja as ReadonlyArray<{ type: string; match: string }>) {
    const re = new RegExp(rule.match, "i");
    for (const [name, chaos] of prices.get(rule.type) ?? []) if (re.test(name) && !/Thread$/.test(name)) out.push({ name, chaos });
  }
  return [...new Map(out.map((o) => [o.name, o])).values()].sort((a, b) => b.chaos - a.chaos);
}

// --- atlas presets -----------------------------------------------------------------------------------
interface Preset { mechanic: string; allocated: number; picks: Array<{ id: string; name: string; stats?: string[]; cost: number }>; ids: string[]; points: number; notPicked: string[]; keystones?: Array<{ id: string; name: string; stats?: string[]; allocated?: boolean }> }
async function presets(ctx: Context, mechanics: Array<{ name: string; keys: string }>, points: number): Promise<{ presets: Preset[]; used?: number; total?: number; error?: string }> {
  try {
    const r = await (await ctx.pob.link()).call("farming_atlas", { mechanics: mechanics.map((m) => m.name), keys: Object.fromEntries(mechanics.map((m) => [m.name, m.keys])), points });
    return { presets: r.presets ?? [], used: r.pointsUsed, total: r.pointsTotal };
  } catch (e) { return { presets: [], error: (e as Error).message }; }
}

// --- progression --------------------------------------------------------------------------------------
function progression(tier: number, pinnacleOk: boolean, uberOk: boolean): string[] {
  const F = D.facts;
  const here = (cond: boolean, next: boolean) => (cond ? "done/able" : next ? "YOU ARE HERE" : "later");
  const stage = tier >= 16 ? (pinnacleOk ? (uberOk ? 5 : 4) : 3) : tier >= 11 ? 2 : tier >= 6 ? 1 : 0;
  const steps = [
    `White maps T1-5 (area level 68-72): complete each map with a magic or better map for its bonus objective = 1 atlas passive point ("${F.bonusPoints.quote}"); up to 10 more points from 10 different unique maps.`,
    `Yellow maps T6-10 (73-77): bonus objectives need rare maps. Three maps of one tier sell to a vendor for one map a tier higher.`,
    `Red maps T11-16 (78-83): bonus objectives need corrupted rare maps; map bosses drop maps up to 2 tiers higher.`,
    `Voidstones (pinnacle bosses): ${F.voidstones.map((v) => `${v.name} from ${v.bosses.join(" + ")}`).join("; ")}. Each one raises its Atlas quadrant to tier 16 ("${F.voidstoneEffect.quote}") and turns lower maps that drop there into Gold.`,
    `Nightmare maps (the former "T17", area level 83): T16 maps can drop as Nightmare maps once voidstones are socketed (${F.nightmareChance.quote.replace(/^resulting in a /, "")}); they are "${F.nightmareBridge.quote.replace(/^These maps are meant to act as /, "")}".`,
    `Uber pinnacle bosses: entered with Uber fragments from Nightmare map bosses; the normal version must be beaten first.`,
  ];
  return [
    `3. PROGRESSION PATH (atlas passive points: ${F.atlasPointsTotal.value} in total this league)`,
    ...steps.map((s, i) => `${i + 1}. [${here(i < stage, i === stage)}] ${s}`),
  ];
}

// --- SSF farm targets -----------------------------------------------------------------------------------
async function ssfTargets(ctx: Context): Promise<string[]> {
  const lines: string[] = [];
  try {
    const own = (await (await ctx.pob.link()).call("economy_items")).result as { items: Array<{ name?: string; rarity?: string; slot?: string }> };
    const uniques = [...new Set(own.items.filter((i) => i.rarity === "UNIQUE" && i.name).map((i) => i.name!))].slice(0, 8);
    if (uniques.length) {
      lines.push(`The build's uniques (${uniques.join(", ")}): kb_lookup each name for where it drops (wiki drop sources, divination cards). Uniques with no special source drop anywhere at their item level, so any strategy with many rares helps.`);
    }
  } catch { /* the rest of the plan stands */ }
  lines.push(`Threads come only from drops in SSF: "${D.facts.frayed.quote}" ${D.facts.shaped.quote} (patch notes).`);
  return lines;
}

// --- money plan ---------------------------------------------------------------------------------------
async function goalChaos(goal: string, league: string, notes: string[]): Promise<{ chaos: number; text: string }> {
  try {
    const b = await budgetOf(goal, league, notes);
    return { chaos: b.chaos, text: goal };
  } catch { /* maybe an item name */ }
  for (const type of ["UniqueWeapon", "UniqueArmour", "UniqueAccessory", "UniqueJewel", "UniqueFlask"]) {
    try {
      const lines = (await ninjaItemLines(league, type)).filter((l) => l.name.toLowerCase() === goal.toLowerCase() && !l.links);
      if (lines.length) {
        const cheapest = lines.sort((a, b) => a.chaosValue - b.chaosValue)[0];
        return { chaos: cheapest.chaosValue, text: `${cheapest.name} (poe.ninja ${n(cheapest.chaosValue)}c)` };
      }
    } catch { /* next type */ }
  }
  throw new ToolError(`goal "${goal}": give an amount ("5 div", "800c") or a unique item's exact name.`);
}

// --- entry point --------------------------------------------------------------------------------------
export async function farmingText(ctx: Context, a: FarmArgs): Promise<string> {
  const profile = getProfile().profile;
  const ssf = profile.playMode === "ssf";

  // Logging a session: player data only, nothing in the build changes.
  if (a.log && typeof a.log === "object") {
    const l = a.log as Record<string, unknown>;
    const s = strategyById(String(l.strategy ?? a.farm ?? ""));
    if (!s) throw new ToolError(`log.strategy must be one of: ${D.strategies.map((x) => x.id).join(", ")}.`);
    const maps = Number(l.maps), minutes = Number(l.minutes), chaos = Number(l.chaos), spent = Number(l.spent ?? 0);
    if (!(minutes > 0) || !(chaos >= 0)) throw new ToolError("log needs minutes (> 0) and chaos (what the loot is worth); maps and spent (Threads, maps) are optional.");
    addLog({ strategy: s.id, maps: maps > 0 ? maps : 0, minutes, chaos, spent: spent > 0 ? spent : 0, at: new Date().toISOString().slice(0, 10), league: a.league });
    const m = measuredRate(s.id, a.league)!;
    return `Logged ${s.name}: ${n(chaos)}c of loot${spent ? ` for ${n(spent)}c spent` : ""} in ${n(minutes)} min. Your measured rate for ${s.name}: ${n(m.perHour)}c/hour net over ${m.sessions} session(s), ${n(m.minutes)} min (your own numbers, not a prediction).`;
  }

  // A strategy asked for (checked before the simulation).
  const asked = typeof a.farm === "string" && a.farm.trim() && a.farm !== "true" ? strategyById(a.farm) : undefined;
  if (typeof a.farm === "string" && a.farm.trim() && a.farm !== "true" && !asked) throw new ToolError(`Unknown strategy "${a.farm}". Strategies: ${D.strategies.map((x) => x.id).join(", ")}.`);

  const link = await ctx.pob.link();
  const levels = [...new Set([1, 5, 6, 10, 11, 14, 16].map((t) => tierLevels().find((x) => x.tier === t)!.level))];
  const check = (await link.call("farming_check", { levels, mods: true })) as CheckResult & { ok: boolean };
  const cap = capabilityText(check, profile.hardcore);
  const top = cap.verdicts.find((v) => v.tier === Math.max(1, Math.min(16, cap.tier || 1)))!;
  const pinnacleOk = survival(check.pinnacle.hits, profile.hardcore) === "safe";
  const uberOk = survival(check.uber.hits, profile.hardcore) === "safe";

  const ranked = D.strategies.map((s) => ({ s, ...fit(s, top, check, profile.hardcore) })).sort((x, y) => y.score - x.score);
  const chosen = asked ? ranked.filter((x) => x.s.id === asked.id) : ranked.slice(0, 3);

  const notes = new Set<string>();
  const types = ["Fragment", "Currency", ...chosen.flatMap((c) => (c.s.ninja as ReadonlyArray<{ type: string }>).map((x) => x.type))];
  const { prices, at } = await categoryPrices(a.league, types, notes);
  const { presets: pre, used, total, error } = await presets(ctx, chosen.map((c) => ({ name: c.s.atlas, keys: c.s.keys })), a.points ?? 30);

  const lines: string[] = [
    `Farming advisor (${D.league}, PoE ${D.version}; content facts from the wiki and GGG's patch notes, cited at the end). Profile: ${profile.playMode}${profile.hardcore ? ", hardcore" : ""}; league ${a.league}.`,
    "",
    ...cap.lines,
    "",
    `2. STRATEGIES ${asked ? "" : "THE BUILD CAN RUN (ranked by fit at T" + top.tier + ")"}`,
    `Map device (new to PoE1): opening a map from the Atlas, you can add Threads: "${D.facts.threads.quote}". ${D.facts.threadsFirst.quote}. Threads replaced Scarabs in ${D.version} ("${D.facts.scarabsGone.quote.split(". ")[0]}."). "${D.facts.threadToughness.quote}" More is not always better: "${D.facts.threadScaling.quote}". Maps in a Shaped Region of that type get free Threads.`,
  ];
  for (const c of chosen) {
    const s = c.s;
    lines.push("", `## ${s.name}  (fit: ${c.why.join(", ")})`);
    lines.push(`- What it is: "${s.what.quote}" (wiki, ${SRC[s.what.src].title})`);
    if ("rewards" in s && s.rewards) lines.push(`- Rewards: "${s.rewards.quote}"`);
    if ("mods" in s && s.mods?.length) lines.push(`- Thread effects include: ${s.mods.map((m) => `"${m.quote}"`).join("; ")}`);
    const p = pre.find((x) => x.mechanic.toLowerCase() === s.atlas.toLowerCase());
    if (p) {
      lines.push(`- Atlas preset (${p.points} points, ${p.allocated} already in ${p.mechanic}): ${p.picks.map((k) => `${k.name} (${oneLine(k.stats)})`).join("; ") || "nothing reachable"}.`);
      if (p.ids.length) lines.push(`  Apply: atlas { add: ${JSON.stringify(p.ids)} } (PoB's Atlas tab shows it; save_build keeps it).`);
      if (p.keystones?.length) lines.push(`  Keystones (trade-offs, pick by hand): ${p.keystones.map((k) => `${k.name} [${k.id}]: ${oneLine(k.stats)}`).join("; ")}.`);
    } else if (error) lines.push(`- Atlas preset not available: ${error}`);
    if ("thread" in s && s.thread) {
      const tp = [...prices.values()].map((m) => m.get(s.thread!)).find((v) => v !== undefined);
      lines.push(tp !== undefined
        ? `- Investment: ${s.thread} ${n(tp, 1)}c each (poe.ninja ${at ? day(at) : ""}): 1 Thread ${n(tp, 1)}c, 4 = ${n(tp * 4)}c, 8 = ${n(tp * 8)}c per map, plus the map.`
        : `- Investment: ${s.thread} is not priced on poe.ninja yet (new item in ${D.version}); maps in a ${s.name} Shaped Region get free ones.`);
    }
    const outs = outputs(s, prices).slice(0, 4);
    lines.push(outs.length
      ? `- What it yields is worth now (poe.ninja ${at ? day(at) : ""}, estimates): ${outs.map((o) => `${o.name} ${n(o.chaos, o.chaos < 10 ? 1 : 0)}c`).join(", ")}.`
      : `- Its outputs are not priced on poe.ninja (yet), so no value estimate.`);
    const m = measuredRate(s.id, a.league);
    lines.push(m
      ? `- Profit per hour (measured by you): ${n(m.perHour)}c/h net over ${m.sessions} session(s), ${n(m.minutes)} min (last ${m.last}).`
      : `- Profit per hour: not measured yet. Drop rates are not published, so the advisor does not invent one: after a session, atlas { log: { strategy: "${s.id}", maps, minutes, chaos, spent } }.`);
  }
  if (used !== undefined) lines.push("", `Atlas now: ${used} / ${total} points used.`);

  lines.push("", ...progression(cap.tier, pinnacleOk, uberOk));

  // Money plan / SSF.
  lines.push("");
  if (ssf) {
    lines.push("4. SSF: FARM FOR WHAT THE BUILD NEEDS (no trading)", ...(await ssfTargets(ctx)).map((l) => `- ${l}`),
      `- Materials: ${ranked.filter((x) => (x.s.ninja as readonly unknown[]).length).slice(0, 4).map((x) => `${x.s.name} (${"rewards" in x.s && x.s.rewards ? x.s.rewards.quote : x.s.what.quote})`).join("; ")}.`,
      "- Gear to keep from drops per slot: plan_upgrades { budget: \"all\" } shows the stats a rare needs.");
  } else if (typeof a.goal === "string" && a.goal.trim()) {
    const ns: string[] = [];
    const g = await goalChaos(a.goal.trim(), a.league, ns);
    let have = 0;
    try { have = (await budgetOf("all", a.league, ns)).chaos; } catch { /* no currency in the profile */ }
    const need = Math.max(0, g.chaos - have);
    lines.push(`4. MONEY PLAN: ${g.text} = ${n(g.chaos)}c; on hand ${n(have)}c (profile); still needed ${n(need)}c.`);
    for (const c of chosen) {
      const m = measuredRate(c.s.id, a.league);
      lines.push(m && m.perHour > 0
        ? `- ${c.s.name}: about ${(need / m.perHour).toFixed(1)} hours at your measured ${n(m.perHour)}c/h.`
        : `- ${c.s.name}: hours unknown until you log a session (atlas { log }).`);
    }
    lines.push(`- What the money buys, simulated: plan_upgrades { budget: "${a.goal.trim()}" }.`);
    ns.forEach((x) => notes.add(x));
  } else {
    lines.push(`4. MONEY PLAN: give goal ("5 div" or a unique's name) to see how long each strategy takes at your measured rate; plan_upgrades { budget } shows what an amount buys.`);
  }

  if (a.leagueNote) notes.add(a.leagueNote);
  if (notes.size) lines.push("", "Notes:", ...[...notes].map((x) => `- ${x}`));
  const used_ = new Set(["patch", "tiers", "voidstone", "nightmare", "thread", "delirium", "simulacrum", "rarity", "map", "atlas", ...chosen.map((c) => c.s.what.src)]);
  lines.push("", `Sources (data file ${D.generated}; re-checked each league):`,
    ...[...used_].map((k) => SRC[k]).filter(Boolean).map((s) => `- ${s.title}: ${s.url}${s.edited ? ` (edited ${s.edited})` : ""}${s.outdated ? " - may be outdated (edited before the league started)" : ""}`),
    `- Advisor rules (not game facts): ${D.rules.note} Safe = at least ${profile.hardcore ? D.rules.hitsSafeHardcore : D.rules.hitsSafe} hits to die; a rare dies within ${D.rules.rareKillComfortable} s.`);
  return lines.join("\n");
}
